		_actionIDs=_actionIDs + [_aid];
		for "_sti" from 0 to _stc-1 do {
			_stp = (_st select _sti);
			_out = _out + format["Turret #%1, %2: [%1,%3]\n",_mti,configName(_stp),_sti];
			_weaps = getArray(_stp >> "weapons");
