|s1= [[systemTimeUTC]]

|r1= [[Array]] with [year, month, day, hour, minute, second, millisecond]
* year: [[Number]]
* month: [[Number]]
* day: [[Number]]
* hour: [[Number]]
* minute: [[Number]]
