|x2= Since 2.10: <sqf>_deadUnit awake true;</sqf>
|x3= Make corpse react to explosion (since 2.10): <sqf>
_deadUnit addEventHandler ["Explosion", 
{
	params ["_unit", "_damage"];
	if (_damage < 0.01) exitWith {};
	_unit awake true;
	_unit awake false;
}];
