43649.wikitext:
{{RV|type=command

|game1= arma3
|version1= 2.18

|gr1= Multiplayer

|descr= Returns JIP ID of the persistent call generated from JIP queue for the joining player (see [[remoteExec]]).

|s1= [[remoteExecutedJIPID]]

|r1= [[String]] - JIP ID

|x1= <sqf>_jipid = remoteExecutedJIPID;</sqf>

|x2= <sqf>
/* 
Have mission with 2 players.
First player starts local server and executes given code
Second player joins the server and sees the 'all good' message
Second player logs out 
First player kills 'bob'
Second player joins back and sees 'removing JIP call' message
Second player logs out then joins back in, no message as call was removed
*/

private _fnc = 
{
	if (isRemoteExecutedJIP) then
	{
		remoteExecutedJIPID splitString "|" params ["_myID", "_netID"];
		private _obj = objectFromNetId _netID;
		if (!alive _obj) then
		{
			hint "object is dead or deleted, removing JIP call";
			remoteExec ["", remoteExecutedJIPID];
		}
		else
		{
			hint "JIP call, all good, doing something";
		};
	};
};

private _bob = group player createUnit [typeOf player, position player, [], 0, "NONE"];
private _myID = "lalala";
private _jipID = [_myID, netId _bob] joinString "|";
[[], _fnc] remoteExec ["call", 0, _jipId];
</sqf>

|seealso= [[remoteExecutedOwner]] [[isRemoteExecuted]] [[isRemoteExecutedJIP]] [[remoteExec]] [[remoteExecCall]] [[canSuspend]] [[publicVariableClient]] [[admin]] [[owner]] [[clientOwner]] [[groupOwner]] [[didJIPOwner]]
}}

43659.wikitext:
{{RV|type=command

|game1= arma3
|version1= 2.18

|gr1= Strings

|descr= Converts data to {{Link|https://en.wikipedia.org/wiki/JSON|JSON}}.

|s1= [[toJSON]] data

|p1= data - Only certain [[Data Types]] are supported:
* [[Boolean]] - serialized as JSON boolean
* [[Number]] - serialized as JSON number (floating-point)
* [[String]] - serialized as JSON string
* [[Array]] - Serialized as JSON array. Unsupported elements (e.g. [[Object]]s) are converted to JSON null.
* [[HashMap]] - Serialized as JSON object. Only [[String]] keys are supported, other keys are ignored. Unsupported values (e.g. [[Object]]s) are converted to JSON null.
* [[nil]] - serialized as JSON null {{Feature|important|The [[nil]] value can only be passed as a member of an [[Array]] or [[HashMap]]. It cannot be passed directly as the command would simply not execute.}}

|r1= [[String]] - JSON string

|x1= <sqf>
private _result = toJSON ["this", "is", "an", "array"];
</sqf>
Result:
<syntaxhighlight lang="json">
["this","is","an","array"]
</syntaxhighlight>

|x2= <sqf>
private _hashMap = createHashMap;
_hashMap set ["bKey", true];
_hashMap set ["sKey", "Hello there"];
_hashMap set ["oKey", player];
_hashMap set ["nKey", 42];
_hashMap set ["hKey", ["key1", "key2", "yolo"] createHashMapFromArray ["General Kenobi", true, "Hello it's me"]];
toJSON _hashMap;
</sqf>
Result (formatted for readability):
<syntaxhighlight lang="json">
{
	"bKey": true,
	"sKey": "Hello there",
	"oKey": null,
	"nkey": 42,
	"hKey": {
		"key1": "General Kenobi",
		"key2": true,
		"yolo": "Hello it's me"
	}
}
</syntaxhighlight>

|x4= <sqf>
private _jsonPlayer = toJSON player; // empty string - [[Object]] is not supported
</sqf>

|seealso= [[fromJSON]] [[toString]] [[str]]
}}

47092.wikitext:
{{RV|type=command

|game1= arma3
|version1= 2.20

|gr1= GUI Control - Map

|descr= Draws an N sided polygon on the map.

|s1= map [[drawXPolygon]] [n, centre, a, b, angle, color, fill, alignWithMap]

|p1= map: [[Control]]

|p2= n: [[Number]] - number of sides 3..720

|p3= centre: [[Object]] or [[Position#Introduction|Position2D]], [[Position#Introduction|Position3D]] - ellipse's centre

|p4= a: [[Number]] - horizontal (x) radius

|p5= b: [[Number]] - vertical (y) radius

|p6= angle: [[Number]] - angle of rotation in degrees

|p7= color: [[Color|Color (RGBA)]] - line color

|p8= fill: [[String]] - fill texture file or [[Procedural Textures]]. Note that the file texture will not rotate with polygon, use [[drawIcon]] for that. If fill texture is not empty, set line color to white [1,1,1,1]

|p9= alignWithMap: [[Boolean]] - (Optional, default [[true]]) - when [[false]] the shape will not follow map rotation.

|r1= [[Nothing]]

|x1= <sqf>
findDisplay 12 displayCtrl 51 ctrlAddEventHandler ["Draw", 
{
	_this select 0 drawXPolygon [
		5, player, 50, 10, 0, [1, 0, 0, 1], ""
	];
	_this select 0 drawXPolygon [
		3, player, 10, 50, 0, [1, 1, 1, 1], "#(rgb,8,8,3)color(1,0.6,0,1)"
	];
	_this select 0 drawXPolygon [
		12, player, 10, 10, 90, [0, 0, 1, 1], ""
	];
}];
</sqf>

