49400.wikitext:
{{RV|type=command

|game1= arma3
|version1= 2.22

|gr1= Object Manipulation

|descr= Enables or disables the freelook toggle (2x Alt)

|s1= [[enableFreeLook]] enable
|p1= enable: [[Boolean]] - enable or disable the toggle
|r1= [[Boolean]] - Previous state

|x1= <sqf>enableFreeLook true;</sqf>

|x2= <sqf>// a function to get the current state without making changes
private _fnc_isFreeLookToggled = 
{
  private _oldState = enableFreeLook true; // enable temporarily; get state
  enableFreeLook _oldState;
  _oldState; // return the state
};

private _isFreeLookToggled = call _fnc_isFreeLookToggled;

// a function to toggle the state
private _fnc_toggleFreeLook = 
{
  enableFreeLook !enableFreeLook false;
};

call _fnc_toggleFreeLook; // toggle it (if enabled->disable it, and vice versa)
</sqf>

|seealso= [[freeLook]]
}}

49402.wikitext:
{{RV|type=command

|game1= arma3
|version1= 2.22

|arg= global

|gr1= Object Manipulation
|gr2= Render Time Scope

|descr= Returns the aim direction and up vectors of a soldier in model space. It returns where the weapon aim is wanted from the [[eyePos]], not the actual weapon direction. For actual weapon direction, see [[weaponDirection]].

|s1= [[getAimDirectionAndUp]] [soldier, isRenderScope]

|p1= soldier: [[Object]] - The soldier entity. The soldier must either be on foot or in a turret.

|p2= isRenderScope: [[Boolean]] - (Optional, default false) Whether to use render scope to get the vector. (render scope is smoother for visualizing the vector in 3D)

|r1= [[Array]] - in format [directionForward, directionUp] in soldier's model space

|x1= <sqf>onEachFrame
{
    getAimDirectionAndUp [player] params ["_dir", "_up"];
    private _dirWS = player vectorModelToWorld _dir;
    private _upWS = player vectorModelToWorld _up;
    private _eyePos = eyePos player;
    drawLine3D [ASLtoAGL _eyePos, ASLtoAGL (_eyePos vectorAdd _dirWS), [1,0,0,1]];
}
</sqf>

|seealso= [[weaponDirection]] [[eyeDirection]] [[positionCameraToWorld]] [[eyePos]]
}}

49403.wikitext:
{{RV|type=command

|game1= arma3
|version1= 2.22

|arg= global

|gr1= Object Manipulation

|descr= Returns the primary and secondary animations queue of the entity. The primary queue contains the full motion path from current animation ([[animationState]]) to a target animation, while the secondary queue contains animations that are queued to be played after the target animation in primaryQueue is reached, e.g. due to using [[playMove]] or [[playAction]].

|s1= [[getAnimationsQueue]] entity

|p1= entity: [[Object]] - Man or animal object.

|r1= [[Array]] - in format [primaryQueue, secondaryQueue] where each queue is an [[Array]] of [[String]]s, the animation state names (all lower case).

|x1= <sqf>getAnimationsQueue player params ["_primaryQueue", "_secondaryQueue"];
if (_secondaryQueue isNotEqualTo []) then { 
    private _targetAnim = _primaryQueue param [count _primaryQueue - 1, animationState player];
    private _nextAnim = _secondaryQueue#0;
    systemChat format ["Will play '%1' after completing '%2'", _nextAnim, _targetAnim]; 
};
</sqf>

|x2= <sqf>player playMove _myMove; // push an animation state to the secondary queue
player playAction "WalkF"; // an action that gets mapped to an animation state and pushed to queue
getAnimationsQueue player params ["_primaryQueue", "_secondaryQueue"];
// _secondaryQueue will contain _myMove and the animation that the "WalkF" action maps to
</sqf>

|seealso= [[animationState]] [[getUnitMovesInfo]]
}}
